import { normalizePath } from "../diff/deepDiff";
import {
  SUMMARIZED_PATTERN,
  fieldLabel,
  groupChanges,
  isScalar,
  summarizeGroup,
  valueChange,
  type ChangeGroup,
} from "../diff/summarize";
import type { CategoryDiff, EntityDiff, EntityStatus } from "../diff/types";
import { classify, impactText } from "../impact/classify";

export interface MarkdownOptions {
  from: string;
  to: string;
  categories?: readonly string[];
}

export const MARKDOWN_FOOTER =
  "_Generated by warpuppywiki from warpuppies/wardogs-data. Unofficial; numbers from the game files._";

function lowerFirst(text: string): string {
  const [first = "", second = ""] = text;
  return second !== "" && second === second.toUpperCase() && second !== second.toLowerCase()
    ? text
    : first.toLowerCase() + text.slice(1);
}

function groupText(categoryId: string, entity: EntityDiff, group: ChangeGroup): string {
  const change = group.changes[0]!;
  const simple =
    group.setPath === null &&
    change.kind === "changed" &&
    normalizePath(change.path) !== SUMMARIZED_PATTERN &&
    isScalar(change.before) &&
    isScalar(change.after) &&
    change.before !== null &&
    change.after !== null;
  if (!simple) {
    return lowerFirst(summarizeGroup(group));
  }
  const text = `${lowerFirst(fieldLabel(change.path))} ${valueChange(change.path, change.before, change.after)}`;
  const label = impactText(classify(categoryId, change, entity.key));
  return label === null ? text : `${text} (${label.toLowerCase()})`;
}

function entityLine(categoryId: string, entity: EntityDiff): string {
  const parts = groupChanges(entity.changes).map((group) => groupText(categoryId, entity, group));
  return `- **${entity.name}:** ${parts.join("; ")}`.replace(/\s*\n\s*/g, " ");
}

function namesLine(diff: CategoryDiff, status: Exclude<EntityStatus, "changed">, title: string): string[] {
  const names = diff.entities.filter((entity) => entity.status === status).map((entity) => entity.name);
  return names.length === 0 ? [] : [`**${title}:** ${names.join(", ")}`];
}

function categoryBlocks(diff: CategoryDiff): string[] {
  const changed = diff.entities.filter((entity) => entity.status === "changed");
  const bullets = [...diff.notes.map((note) => `- ${note}`), ...changed.map((entity) => entityLine(diff.id, entity))];
  return [
    `### ${diff.label}`,
    ...namesLine(diff, "added", "Added"),
    ...namesLine(diff, "removed", "Removed"),
    ...(bullets.length > 0 ? [bullets.join("\n")] : []),
  ];
}

export function toMarkdown(diffs: readonly CategoryDiff[], { from, to, categories }: MarkdownOptions): string {
  const selected = diffs.filter(
    (diff) =>
      (categories === undefined || categories.includes(diff.id)) && (diff.entities.length > 0 || diff.notes.length > 0),
  );
  const blocks = [
    `## Wardogs data changes: build ${from} → ${to}`,
    ...selected.flatMap(categoryBlocks),
    MARKDOWN_FOOTER,
  ];
  return `${blocks.join("\n\n")}\n`;
}
